157	fn canonical_artifact_root(artifact_root: &Path) -> Result<PathBuf, GraphError> {
158	    let metadata = fs::metadata(artifact_root).map_err(|error| GraphError::ArtifactRead {
159	        path: artifact_root.to_path_buf(),
160	        message: error.to_string(),
161	    })?;
162	    if !metadata.is_dir() {
163	        return Err(GraphError::UnsafeArtifactPath {
164	            path: artifact_root.to_path_buf(),
165	            reason: "artifact root is not a directory",
166	        });
167	    }
168	    artifact_root.canonicalize().map_err(|error| GraphError::ArtifactRead {
169	        path: artifact_root.to_path_buf(),
170	        message: error.to_string(),
171	    })
172	}
