 49	    fn preflight(
 50	        &self,
 51	        context: &ProviderContext<'_>,
 52	        request: &ProviderRequest<'_>,
 53	    ) -> Result<ReleasePreflight, GraphError> {
 54	        adapter_for(request.id.package.ecosystem())?.preflight(
 55	            context,
 56	            request.id,
 57	            registry_operation(request)?,
 58	            request.artifacts,
 59	        )
 60	    }
