196	impl ArtifactManifestV1 {
197	    pub const SCHEMA_VERSION: u8 = 1;
198	
199	    pub fn new(intent: &ReleaseIntentV1, entries: Vec<ArtifactManifestEntryV1>) -> Result<Self, ArtifactManifestError> {
200	        Self::with_distributions(intent, entries, Vec::new())
201	    }
202	
203	    pub fn with_distributions(
204	        intent: &ReleaseIntentV1,
205	        mut entries: Vec<ArtifactManifestEntryV1>,
206	        mut distributions: Vec<DistributionSetV1>,
207	    ) -> Result<Self, ArtifactManifestError> {
208	        let SourceIdentity::GitCommit { sha } = &intent.snapshot.source else {
209	            return Err(ArtifactManifestError::NonGitSource);
210	        };
211	        entries.sort_by(|left, right| left.slot.cmp(&right.slot));
212	        if entries.windows(2).any(|pair| pair[0].slot == pair[1].slot) {
213	            return Err(ArtifactManifestError::DuplicateSlot);
214	        }
215	        let expected = &intent.artifact_slots;
216	        if entries.iter().map(|entry| &entry.slot).ne(expected.iter()) {
217	            return Err(ArtifactManifestError::MismatchedSlotRoster);
218	        }
219	        if entries.iter().any(|entry| {
220	            entry.digest != entry.attestation.subject_digest
221	                || entry.attestation.source_commit != entry.slot.attestation_policy.workflow_commit
222	                || entry.attestation.repository != entry.slot.attestation_policy.repository
223	                || entry.attestation.workflow_path != entry.slot.attestation_policy.workflow_path
224	                || entry.attestation.workflow_commit != entry.slot.attestation_policy.workflow_commit
225	        }) {
226	            return Err(ArtifactManifestError::MismatchedAttestation);
227	        }
228	        distributions.sort_by(|left, right| left.key().cmp(&right.key()));
229	        for set in &mut distributions {
230	            set.files.sort_by(|left, right| left.filename.cmp(&right.filename));
231	        }
232	        validate_distributions(intent, &entries, &distributions)?;
233	        Ok(Self {
234	            schema_version: Self::SCHEMA_VERSION,
235	            intent_digest: intent.digest.clone(),
236	            source_commit: sha.clone(),
237	            entries,
238	            distributions,
239	        })
240	    }
