242	    /// Hashes the canonical serialized manifest transported from build to
243	    /// execution. Its entry roster was canonicalized by [`Self::new`].
244	    pub fn digest(&self) -> ArtifactDigest {
245	        ArtifactDigest::from_bytes(serde_json::to_vec(self).expect("artifact manifest serializes"))
246	    }
247	
248	    pub fn validate_for_intent(&self, intent: &ReleaseIntentV1) -> Result<(), ArtifactManifestError> {
249	        if self.schema_version != Self::SCHEMA_VERSION || self.intent_digest != intent.digest {
250	            return Err(ArtifactManifestError::MismatchedIntent);
251	        }
252	        match &intent.snapshot.source {
253	            SourceIdentity::GitCommit { sha } if sha == &self.source_commit => {}
254	            SourceIdentity::GitCommit { .. } => return Err(ArtifactManifestError::MismatchedSourceCommit),
255	            SourceIdentity::HermeticContent { .. } => return Err(ArtifactManifestError::NonGitSource),
256	        }
257	        Self::with_distributions(intent, self.entries.clone(), self.distributions.clone()).map(|_| ())
258	    }
259	}
