261	/// The versions the intent publishes to a Python registry.
262	pub fn python_publishes(intent: &ReleaseIntentV1) -> Vec<(&ReleasePackageId, String)> {
263	    let mut publishes: Vec<_> = intent
264	        .operations
265	        .iter()
266	        .map(|operation| operation.id())
267	        .filter(|id| id.package.ecosystem() == Ecosystem::Pypi)
268	        .filter(|id| matches!(id.role, ReleaseOperationRole::RegistryPublish { .. }))
269	        .map(|id| (&id.package, id.version.render().to_string()))
270	        .collect();
271	    publishes.sort();
272	    publishes.dedup();
273	    publishes
274	}
