 90	/// Every wheel and sdist of `package_name` at `version` directly in `dir`, with its digest, by filename.
 91	fn inventory(dir: &Path, package_name: &str, version: &Version) -> Result<Vec<BuiltFile>, GraphError> {
 92	    let wanted = normalize_pypi_project_name(package_name);
 93	    let mut files = Vec::new();
 94	    for entry in std::fs::read_dir(dir).map_err(io_error)? {
 95	        let path = entry.map_err(io_error)?.path();
 96	        let Some(filename) = path.file_name().and_then(|name| name.to_str()).map(str::to_owned) else {
 97	            continue;
 98	        };
 99	        let belongs = dist_filename_parts(&filename).is_some_and(|(name, candidate)| {
100	            normalize_pypi_project_name(name) == wanted && is_version(candidate, version)
101	        });
102	        if !belongs {
103	            continue;
104	        }
105	        let sha256 = format!("{:x}", Sha256::digest(std::fs::read(&path).map_err(io_error)?));
106	        files.push(BuiltFile { filename, path, sha256 });
107	    }
108	    files.sort_by(|left, right| left.filename.cmp(&right.filename));
109	    for (present, missing) in [
110	        (files.iter().any(|file| is_wheel(&file.filename)), "wheel"),
111	        (files.iter().any(|file| is_sdist(&file.filename)), "sdist"),
112	    ] {
113	        if !present {
114	            return Err(GraphError::PypiBuildOutputIncomplete {
115	                package: package_name.to_string(),
116	                version: version.clone(),
117	                missing,
118	            });
119	        }
120	    }
121	    Ok(files)
122	}
