136	    /// The files a build job sealed, already checked byte for byte against the manifest.
137	    pub(super) fn sealed(files: Vec<BuiltFile>, package_name: &str, version: &Version) -> Result<Self, GraphError> {
138	        let wanted = normalize_pypi_project_name(package_name);
