147	                    stray.filename,
148	                    version.render()
149	                ),
150	            });
151	        }
152	        Ok(Self {
153	            _dir: None,
154	            files,
155	            sealed: true,
156	            uploaded: Mutex::new(Vec::new()),
157	        })
158	    }
