187	/// The sealed file set of every Python publish in `intent`, from the build output in `dir`.
188	pub(crate) fn seal_distributions(
189	    intent: &callisto_model::ReleaseIntentV1,
190	    dir: &Path,
191	) -> Result<Vec<callisto_model::DistributionSetV1>, GraphError> {
192	    let mut sets = Vec::new();
193	    for (package, rendered) in callisto_model::python_publishes(intent) {
194	        let version = intent
195	            .operations
196	            .iter()
197	            .map(|operation| operation.id())
198	            .find(|id| id.package == *package && id.version.render() == rendered)
199	            .map(|id| id.version.clone())
200	            .expect("a Python publish listed from the intent is in the intent");
201	        let files = inventory(dir, package.name(), &version)?
202	            .into_iter()
203	            .map(|file| {
204	                let byte_length = std::fs::metadata(&file.path).map_err(io_error)?.len();
205	                let digest = callisto_model::ArtifactDigest::parse(&file.sha256)
206	                    .expect("a SHA-256 hex digest is a canonical artifact digest");
207	                Ok(callisto_model::DistributionFileV1 {
208	                    filename: file.filename,
209	                    digest,
210	                    byte_length,
211	                })
212	            })
213	            .collect::<Result<Vec<_>, GraphError>>()?;
214	        sets.push(callisto_model::DistributionSetV1 {
215	            package: package.clone(),
216	            version: rendered,
217	            files,
218	        });
219	    }
220	    Ok(sets)
221	}
