112	/// Requires the verification capability whenever `intent` declares compiled
113	/// binary slots. Its private constructor already proved both manifest binding
114	/// and local byte/attestation identity.
115	fn require_verified_artifact_manifest(
116	    intent: &ReleaseIntentV1,
117	    artifacts: Option<&VerifiedArtifactManifest<'_>>,
118	) -> Result<(), GraphError> {
119	    match (intent.artifact_slots.is_empty(), artifacts) {
120	        (true, None) => Ok(()),
121	        (true, Some(artifacts)) if !callisto_model::python_publishes(intent).is_empty() => {
122	            require_artifact_manifest_matches_intent(intent, Some(artifacts.manifest()))
123	        }
124	        (true, Some(_)) => Err(GraphError::ReleaseInvariant {
125	            detail: "verified artifact manifest supplied for a release intent with nothing to seal".to_owned(),
126	        }),
127	        (false, Some(artifacts)) => require_artifact_manifest_matches_intent(intent, Some(artifacts.manifest())),
128	        (false, None) => Err(GraphError::ReleasePreconditionUnmet {
129	            requirement: ReleasePreconditionRequirement::VerifiedArtifactManifest,
130	        }),
131	    }
132	}
133	
134	/// Validates the serializable manifest independently of local byte and
135	/// attestation verification. Kept as a focused invariant helper for tests;
136	/// production execution requires `VerifiedArtifactManifest` above.
137	fn require_artifact_manifest_matches_intent(
138	    intent: &ReleaseIntentV1,
139	    artifacts: Option<&callisto_model::ArtifactManifestV1>,
140	) -> Result<(), GraphError> {
141	    match (intent.artifact_slots.is_empty(), artifacts) {
142	        (true, None) => Ok(()),
143	        (true, Some(manifest)) | (false, Some(manifest)) => manifest
144	            .validate_for_intent(intent)
145	            .map_err(|source| GraphError::ArtifactManifest { source }),
146	        (false, None) => Err(GraphError::ReleasePreconditionUnmet {
147	            requirement: ReleasePreconditionRequirement::ArtifactManifestProvided,
148	        }),
149	    }
150	}
