   340	/// `twine upload` of exactly `files`, never a glob or `--skip-existing`, which skips by name without comparing bytes.
   500	/// Priority order (highest wins):
   501	/// 1. A successful run printing `"already exist"` (twine's `--skip-existing` message) without `"uploading"` ->
   502	///    [`PublishOutcome::AlreadyPublished`]. Callisto passes no `--skip-existing`, so a conflict is a failing run and
   503	///    falls through to `RegistryError::Other` below, which is the intended fail-closed outcome.
   504	/// 2. Zero exit code with no skip-only mention -> [`PublishOutcome::Published`].
   505	/// 3. Rate-limit signal (`429`, `too many requests`, `rate limit`) ->
   506	///    [`RegistryError::RateLimited`] with a parsed or default 60-second
   507	///    retry-after duration.
   508	/// 4. Auth-failure signal (`401`, `403`, `authentication`, etc.) ->
   509	///    [`RegistryError::AuthFailed`].
   510	/// 5. Anything else -> [`RegistryError::Other`].
   511	pub(crate) fn classify_twine_output(output: &CommandOutput) -> Result<PublishOutcome, RegistryError> {
   512	    let combined = combined_lower(output);
   513	
   514	    let has_skip = combined.contains("already exist");
   515	    let has_upload = combined.contains("uploading");
   516	    if has_skip && !has_upload && output.success() {
   517	        return Ok(PublishOutcome::AlreadyPublished);
   518	    }
   519	    if output.success() {
   520	        return Ok(PublishOutcome::Published);
   521	    }
   522	    if let Some(err) = detect_rate_limit(&combined) {
   523	        return Err(err);
   524	    }
   525	    if let Some(err) = detect_auth_failure(&combined, output) {
   526	        return Err(err);
   527	    }
   528	    let progress = callisto_model::redact_command_stderr(&output.stdout);
   529	    let progress: Vec<_> = progress.lines().rev().take(8).collect();
   530	    Err(RegistryError::Other(format!(
   531	        "twine upload failed (exit {:?}): {}{}",
   532	        output.exit_code,
   533	        progress.into_iter().rev().collect::<Vec<_>>().join("\n"),
   534	        output.redacted_stderr().trim_end()
   535	    )))
   536	}
