811	/// Resolves `callisto@<version>`'s commit SHA on `orin-dx/callisto`'s remote.
812	///
813	/// GitHub's runner splits a `uses:` reference at the LAST `@` in the whole
814	/// string (`ActionManifestManagerWrapper.ParseActionReference` in
815	/// `actions/runner`), so a ref that itself contains `@` -- like the
816	/// `callisto@<version>` tag this project releases under -- can never be
817	/// written directly as `owner/repo/path@callisto@<version>`: the split lands
818	/// inside the ref, not before it, and resolution fails. The generated
819	/// workflow pins to this tag's resolved commit instead, like every other
820	/// external action reference in this repository.
821	///
822	/// # Errors
823	///
824	/// The remote is unreachable, or `callisto@<version>` is not a published tag.
825	pub fn resolve_release_commit<R: CommandRunner>(runner: &R, root: &Path, version: &str) -> Result<String, GraphError> {
826	    const ENDPOINT: &str = "https://github.com/orin-dx/callisto.git";
827	    let reference = format!("refs/tags/callisto@{version}");
828	    // The peeled ref resolves an annotated tag to its commit; a lightweight
829	    // tag has no peeled line, and its own SHA already is the commit.
830	    let peeled = format!("{reference}^{{}}");
831	    // A transport-level failure (git not found, timed out, ...) keeps its
832	    // real cause via `GraphError::Command`; only a clean run that still
833	    // can't find the tag becomes `InitWorkflowVersionUnresolved`.
834	    let output = runner.run_quiet(
835	        programs::GIT,
836	        &["ls-remote", ENDPOINT, &reference, &peeled],
837	        root,
838	        timeouts::GIT_LS_REMOTE,
839	    )?;
840	    let unresolved = || GraphError::InitWorkflowVersionUnresolved {
841	        version: version.to_owned(),
842	    };
843	    if output.exit_code != Some(0) {
844	        return Err(unresolved());
845	    }
846	    let mut tag_object = None;
847	    let mut commit = None;
848	    for line in output.stdout.lines() {
849	        let Some((sha, found)) = line.split_once('\t') else {
850	            continue;
851	        };
852	        match found.trim() {
853	            found if found == peeled => commit = Some(sha.trim().to_owned()),
854	            found if found == reference => tag_object = Some(sha.trim().to_owned()),
855	            _ => {}
856	        }
857	    }
858	    commit.or(tag_object).ok_or_else(unresolved)
859	}
