861	/// Renders the release workflow for `shape`.
862	///
863	/// `commit` pins the generated `orin-dx/callisto` action references to the
864	/// resolved commit of `callisto@<version>` (see [`resolve_release_commit`]);
865	/// `version` names the CLI `setup-callisto` installs and a trailing comment.
866	pub fn render_workflow(facts: &InitFacts, shape: WorkflowShape, branch: &str, commit: &str, version: &str) -> String {
867	    let mut secrets = Vec::new();
868	    if facts.ecosystems.contains(&Ecosystem::Cargo) {
869	        secrets.push("CARGO_REGISTRY_TOKEN: ${{ secrets.CARGO_REGISTRY_TOKEN }}".to_owned());
870	    }
871	    if facts.ecosystems.contains(&Ecosystem::Npm) {
872	        secrets.push("NPM_TOKEN: ${{ secrets.NPM_TOKEN }}".to_owned());
873	        // Uses the job's id-token: write; npm publishes no provenance without it.
874	        secrets.push("NPM_CONFIG_PROVENANCE: \"true\"".to_owned());
875	    }
876	    if facts.ecosystems.contains(&Ecosystem::Pypi) {
877	        secrets.push("PYPI_TOKEN: ${{ secrets.PYPI_TOKEN }}".to_owned());
878	    }
879	    secrets.push("GH_TOKEN: ${{ github.token }}".to_owned());
880	    let env_lines: Vec<String> = secrets.iter().map(|line| format!("          {line}")).collect();
881	    let release_env = format!("env:\n{}", env_lines.join("\n"));
882	
883	    let template = match shape {
884	        WorkflowShape::Simple => WORKFLOW_TEMPLATE,
885	        WorkflowShape::BuildMatrix => MATRIX_WORKFLOW_TEMPLATE,
886	    };
887	    let python_tools = if facts.ecosystems.contains(&Ecosystem::Pypi) {
888	        SIMPLE_PYTHON_TOOLS_STEP
889	    } else {
890	        ""
891	    };
892	    template
893	        .replace("      __PYTHON_TOOLS__\n", python_tools)
894	        .replace("__BUILD__", BUILD_REQUIREMENT)
895	        .replace("__TWINE__", TWINE_REQUIREMENT)
896	        .replace("__BRANCH__", branch)
897	        .replace("__COMMIT__", commit)
898	        .replace("__VERSION__", version)
899	        .replace("        __RELEASE_ENV__", &format!("        {release_env}"))
900	}
