pub fn resolve_commit(&self, refname: &str) -> Result<Option<CommitSha>, VcsError> {
    let rev = format!("{refname}^{{commit}}");
    let output = self
        .runner
        .run("git", &["rev-parse", "--verify", "--quiet", &rev], &self.root)?;

    if !output.success() {
