use callisto_model::vcs::GitAccess;
use callisto_model::{
    select_last_tag, CommitSha, Diagnostic, Ecosystem, LastTag, LastTagSelection, PackageId, TagTemplate,
    VersionGrammar,
};

use crate::config::ResolvedConfig;
