/// Regenerates the lockfile of each active ecosystem with the ecosystem's own tool. For Python,
/// exactly one lockfile is refreshed, in uv, poetry, pdm order.
fn refresh_lockfiles<R: CommandRunner>(
    runner: &R,
    root: &Path,
    cargo_workspaces: &BTreeSet<PathBuf>,
    lockfile_dirs: &LockfileDirs,
) -> Result<Vec<LockfileRefreshResult>, GraphError> {
    let mut refresh_results: Vec<LockfileRefreshResult> = Vec::new();

    for workspace in cargo_workspaces {
        let lockfile = cargo_lockfile(workspace);
        refresh_results.push(run_lockfile_refresh(
            runner,
            &root.join(workspace.parent().unwrap_or(Path::new(""))),
            &lockfile.to_string_lossy(),
            "cargo",
            &["update", "--workspace"],
        )?);
    }

    for dir in &lockfile_dirs.pypi {
        for (file, program, args) in PYPI_REFRESH {
            if path_exists(root, &dir.join(file))? {
                refresh_results.push(refresh_in(runner, root, dir, file, program, args)?);
                break;
            }
        }
    }

    for dir in &lockfile_dirs.npm {
        for (file, program, args) in NPM_REFRESH {
            if path_exists(root, &dir.join(file))? {
                refresh_results.push(refresh_in(runner, root, dir, file, program, args)?);
            }
        }
        for file in ["bun.lock", "bun.lockb"] {
            if path_exists(root, &dir.join(file))? {
                refresh_results.push(refresh_in(
                    runner,
                    root,
                    dir,
                    file,
                    "bun",
                    &["install", "--lockfile-only"],
                )?);
                break;
            }
        }
    }

    Ok(refresh_results)
}

type Refresh = (&'static str, &'static str, &'static [&'static str]);

/// For Python exactly one lockfile is refreshed per directory, in this order.
const PYPI_REFRESH: [Refresh; 3] = [
    ("uv.lock", "uv", &["lock"]),
    ("poetry.lock", "poetry", &["lock", "--no-update"]),
    ("pdm.lock", "pdm", &["lock", "--update-reuse"]),
];

/// Each npm-family lockfile present is refreshed independently (bun's two spellings are handled apart).
const NPM_REFRESH: [Refresh; 3] = [
    (
        "package-lock.json",
        "npm",
        &["install", "--package-lock-only", "--ignore-scripts"],
    ),
    ("pnpm-lock.yaml", "pnpm", &["install", "--lockfile-only"]),
    ("yarn.lock", "yarn", &["install", "--mode", "update-lockfile"]),
];

const NPM_LOCKFILES: [&str; 5] = [
    "package-lock.json",
    "pnpm-lock.yaml",
    "yarn.lock",
    "bun.lock",
    "bun.lockb",
];
const PYPI_LOCKFILES: [&str; 4] = ["uv.lock", "poetry.lock", "pdm.lock", "Pipfile.lock"];

/// Runs the refresh of `dir/file` in `dir`, reporting the lockfile by its path from the workspace root.
fn refresh_in<R: CommandRunner>(
    runner: &R,
    root: &Path,
    dir: &Path,
    file: &str,
    program: &str,
    args: &[&str],
) -> Result<LockfileRefreshResult, GraphError> {
    run_lockfile_refresh(
        runner,
        &root.join(dir),
        &dir.join(file).to_string_lossy(),
        program,
        args,
    )
}

use std::path::{Path, PathBuf};

use callisto_model::vcs::{GitAccess, VcsError};
use callisto_model::CommandRunner;

use crate::locate::membership::{parse_error, read_root_manifest};
use crate::locate::LocateError;

/// Finds the root between `start` and its Git toplevel (never above it): the nearest
/// workspace marker, else the outermost package manifest so vendored packages can't shadow it.
///
/// The toplevel comes from `git rev-parse --show-toplevel` (via `runner`), not a hand-rolled
/// walk for a `.git` entry -- `git` alone honors `GIT_DIR`/`GIT_WORK_TREE`/
/// `GIT_CEILING_DIRECTORIES` the way every other Git-aware tool does.
pub fn find_workspace_root(start: &Path, runner: &dyn CommandRunner) -> Result<PathBuf, LocateError> {
    let canonical = dunce::canonicalize(start).unwrap_or_else(|_| start.to_path_buf());
    let toplevel = GitAccess::new(&canonical, runner).toplevel().map_err(|e| match &e {
        VcsError::Git(message) if message.to_lowercase().contains("not a git repository") => {
            LocateError::NotAGitRepository {
                start: start.to_path_buf(),
            }
        }
        _ => LocateError::from(e),
    })?;
    let range = || canonical.ancestors().take_while(|dir| dir.starts_with(&toplevel));
    for dir in range() {
        if is_workspace_root(dir)? {
            return Ok(dir.to_path_buf());
        }
    }
    let mut outermost = None;
    for dir in range() {
        if is_package_root(dir)? {
            outermost = Some(dir);
        }
    }
    outermost
        .map(Path::to_path_buf)
        .ok_or_else(|| LocateError::WorkspaceRootNotFound {
            start: start.to_path_buf(),
            toplevel: toplevel.clone(),
        })
}

/// Loads `dir/Cargo.toml` as a TOML document, or `None` if it does not exist. A manifest that cannot be read or
/// parsed is an error: skipping it would let the search settle on a different root.
fn cargo_document(dir: &Path) -> Result<Option<toml_edit::DocumentMut>, LocateError> {
    let path = dir.join("Cargo.toml");
    read_root_manifest(&path)?
        .map(|content| {
            content
                .parse::<toml_edit::DocumentMut>()
                .map_err(|error| parse_error(&path, error.to_string()))
        })
        .transpose()
}

fn path_exists(path: &Path) -> Result<bool, LocateError> {
    callisto_model::strict_fs::exists(path).map_err(|error| LocateError::ManifestReadError {
        path: path.to_path_buf(),
        message: error.to_string(),
    })
}

/// A single-package repository root: `Cargo.toml` with `[package]`, `package.json`, or `pyproject.toml`.
fn is_package_root(dir: &Path) -> Result<bool, LocateError> {
    // Parsed, so a comment that mentions the name does not count; any spelling of the table does.
    if cargo_document(dir)?.is_some_and(|doc| doc.get("package").is_some_and(toml_edit::Item::is_table_like)) {
        return Ok(true);
    }
    Ok(path_exists(&dir.join("package.json"))? || path_exists(&dir.join("pyproject.toml"))?)
}

fn is_workspace_root(dir: &Path) -> Result<bool, LocateError> {
    if cargo_document(dir)?.is_some_and(|doc| callisto_manifests::declares_workspace(&doc)) {
        return Ok(true);
    }

    let pkg_json = dir.join("package.json");
    if let Some(content) = read_root_manifest(&pkg_json)? {
        let value = serde_json::from_str::<serde_json::Value>(&content)
            .map_err(|error| parse_error(&pkg_json, error.to_string()))?;
        if value.get("workspaces").is_some() {
            return Ok(true);
        }
    }

    Ok(path_exists(&dir.join("pnpm-workspace.yaml"))? || dir.join(".moon").is_dir())
}

