/// The Cargo section a dependency kind is declared in; optional dependencies sit beside runtime ones.
fn section_name(kind: DepKind) -> &'static str {
    match kind {
        DepKind::Dev => "dev-dependencies",
        DepKind::Build => "build-dependencies",
        _ => "dependencies",
    }
}

