use std::collections::BTreeSet;
use std::path::{Component, Path, PathBuf};

use callisto_model::{ApplyPermit, CommandError, CommandRunner};

use super::ApplyOptions;
use crate::cascade::DepWriteTarget;
use crate::error::GraphError;
use crate::plan::{VersionPlan, VersionWriteTarget};

/// What a plan does to a path, which decides what must hold for it.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
enum Target {
    /// A manifest the plan edits: it must exist as a readable regular file and its directory must take a new file.
    Existing,
    /// A file the plan may create or replace, such as a changelog or `pre.json`.
    Creatable,
    /// A file the plan deletes: only the path itself is checked.
    Removed,
}

/// Every path `plan` writes or deletes under `opts`, once each.
fn targets(plan: &VersionPlan, opts: &ApplyOptions) -> BTreeSet<(PathBuf, Target)> {
    let mut targets = BTreeSet::new();
    for bump in &plan.bumps {
        for write in &bump.writes {
            let path = match write {
                VersionWriteTarget::Manifest(path) => path,
                VersionWriteTarget::CargoWorkspacePackage { root_manifest } => root_manifest,
            };
            targets.insert((path.clone(), Target::Existing));
        }
    }
    for rewrite in &plan.rewrites {
        let path = match &rewrite.key.target {
            DepWriteTarget::Manifest(path) => path,
            DepWriteTarget::CargoWorkspaceDependency { root_manifest } => root_manifest,
        };
        targets.insert((path.clone(), Target::Existing));
    }
    targets.extend(
        plan.platform_writes
            .iter()
            .map(|write| (write.manifest.clone(), Target::Existing)),
    );
    targets.extend(
        plan.optional_dep_updates
            .iter()
            .map(|update| (update.manifest.clone(), Target::Existing)),
    );
    if !opts.transient {
        targets.extend(
            plan.changelog_writes
                .iter()
                .map(|write| (write.changelog_path.clone(), Target::Creatable)),
        );
        targets.extend(
            plan.consumed_changesets
                .iter()
                .map(|path| (path.clone(), Target::Removed)),
        );
        if plan.pre_state_update.is_some() {
            targets.insert((plan.pre_json_path.clone(), Target::Creatable));
        } else if let Some(path) = &plan.delete_pre_json {
            targets.insert((path.clone(), Target::Removed));
        }
    }
    targets
}

/// Fails with every target that cannot be written, before anything is.
///
/// # Errors
///
/// [`GraphError::ApplyPreflight`] naming each unwritable path and why.
pub(super) fn check<R: CommandRunner>(
    root: &Path,
    plan: &VersionPlan,
    opts: &ApplyOptions,
    permit: &ApplyPermit,
    runner: &R,
) -> Result<(), GraphError> {
    let targets = targets(plan, opts);
    let mut problems: Vec<String> = targets
        .iter()
        .filter_map(|(path, target)| {
            problem(root, path, *target, permit).map(|reason| format!("`{}`: {reason}", path.display()))
        })
        .collect();
    if !opts.transient {
        let staged: Vec<PathBuf> = targets
            .iter()
            .filter(|(_, target)| *target != Target::Removed)
            .map(|(path, _)| path.clone())
            .collect();
        problems.extend(ignored_paths(runner, root, &staged)?.into_iter().map(|path| {
            format!(
                "`{}`: is ignored by a .gitignore, so Git would not stage it",
                path.display()
            )
        }));
    }
    if problems.is_empty() {
        Ok(())
    } else {
        Err(GraphError::ApplyPreflight { problems })
    }
}

/// The paths of `paths` that a `.gitignore` ignores and Git does not already track, which `git add` refuses.
///
/// # Errors
///
/// `git check-ignore` could not run or failed (anything but "some ignored" and "none ignored").
pub(super) fn ignored_paths<R: CommandRunner>(
    runner: &R,
    root: &Path,
    paths: &[PathBuf],
) -> Result<BTreeSet<PathBuf>, GraphError> {
    if paths.is_empty() {
        return Ok(BTreeSet::new());
    }
    // One quiet run answers the usual "none ignored"; only when something is does each path get asked, so no output
    // needs parsing (git quotes unusual names).
    if !any_ignored(runner, root, paths)? {
        return Ok(BTreeSet::new());
    }
    let mut ignored = BTreeSet::new();
    for path in paths {
        if any_ignored(runner, root, std::slice::from_ref(path))? {
            ignored.insert(path.clone());
        }
    }
    Ok(ignored)
}

/// Whether `git check-ignore` names at least one of `paths` as ignored (it prints what it matched, `-q` taking one path only).
fn any_ignored<R: CommandRunner>(runner: &R, root: &Path, paths: &[PathBuf]) -> Result<bool, GraphError> {
    let rendered: Vec<String> = paths.iter().map(|path| path.to_string_lossy().into_owned()).collect();
    let mut args = vec!["check-ignore", "--"];
    args.extend(rendered.iter().map(String::as_str));
    let output = runner.run("git", &args, root)?;
    match output.exit_code {
        Some(0) => Ok(!output.stdout.trim().is_empty()),
        Some(1) => Ok(false),
        exit_code => Err(GraphError::Command(CommandError::Failed {
            program: "git".to_string(),
            exit_code,
            stderr: output.redacted_stderr(),
        })),
    }
}

fn problem(root: &Path, relative: &Path, target: Target, permit: &ApplyPermit) -> Option<String> {
    if relative.is_absolute()
        || relative
            .components()
            .any(|c| matches!(c, Component::ParentDir | Component::Prefix(_)))
    {
        return Some("is outside the workspace".to_string());
    }
    // Git cannot stage a path through a link, and replacing a link with a file would change what the repo records.
    let mut current = root.to_path_buf();
    for component in relative.components() {
        current.push(component);
        match std::fs::symlink_metadata(&current) {
            Ok(metadata) if metadata.file_type().is_symlink() => {
                return Some("is, or sits beneath, a symbolic link, which Git cannot stage".to_string());
            }
            Ok(_) => {}
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => break,
            Err(error) => return Some(format!("cannot be inspected: {error}")),
        }
    }
    if target == Target::Removed {
        return None;
    }

    python: HashMap<PathBuf, Option<Membership>>,
}

/// Whether the workspaces nested below `root` admit the package of `ecosystem` at `rel`. The workspace at `root` is
/// judged by the `read_*_membership` of each ecosystem; this adds the verdict of a nearer one, which judges the package
/// by its own list. `manifest_text` is the package's own manifest.
pub(crate) fn nested_workspace_admits(
    root: &Path,
    rel: &Path,
    ecosystem: callisto_model::Ecosystem,
    manifest_text: &str,
    nested: &mut NestedMemberships,
) -> Result<bool, LocateError> {
    use callisto_model::Ecosystem;
    match ecosystem {
        Ecosystem::Cargo => nested_cargo_workspace_admits(root, rel, manifest_text, nested),
        Ecosystem::Npm => {
            let cache = &mut nested.npm;
            judged_by_nearest_declared_workspace(
                root,
                rel,
                cache,
                |dir| read_npm_membership(dir).map(|membership| membership.globs.is_some().then_some(membership)),
                |membership, within| membership.admits(within, false),
            )
        }
        Ecosystem::Pypi => {
            let cache = &mut nested.python;
            judged_by_nearest_declared_workspace(
                root,
                rel,
                cache,
                |dir| read_python_membership(dir).map(|membership| membership.declared.then_some(membership)),
                |membership, within| membership.admits(within, false),
            )
        }
        _ => Ok(true),
    }
}

/// The nearest directory above `rel`, below `root`, whose own manifest declares a workspace judges `rel` by its list,
/// with `rel` taken relative to it. With no such directory nothing nested has an opinion.
fn judged_by_nearest_declared_workspace<M>(
    root: &Path,
    rel: &Path,
    cache: &mut HashMap<PathBuf, Option<M>>,
    read: impl Fn(&Path) -> Result<Option<M>, LocateError>,
    admits: impl Fn(&M, &Path) -> bool,
) -> Result<bool, LocateError> {
    for ancestor in rel.ancestors().skip(1) {
        if ancestor.as_os_str().is_empty() || ancestor == Path::new(".") {
            break;
        }
        if !cache.contains_key(ancestor) {
            let membership = read(&root.join(ancestor))?;
            cache.insert(ancestor.to_path_buf(), membership);
        }
        if let Some(membership) = &cache[ancestor] {
            let within = rel.strip_prefix(ancestor).unwrap_or(rel);
            return Ok(admits(membership, within));
        }
    }
    Ok(true)
}

/// Whether a Cargo workspace nested below `root` admits the package at `rel`. The workspace at `root` is judged by
/// [`read_cargo_membership`]; this adds the verdict of a nearer workspace that governs the package, which judges it by its
/// own `members` and `exclude`. A package that is itself a workspace root, or that no nested workspace governs, passes.
pub(crate) fn nested_cargo_workspace_admits(
    root: &Path,
    rel: &Path,
    manifest_text: &str,
    nested: &mut NestedMemberships,
) -> Result<bool, LocateError> {
    let manifest = rel.join("Cargo.toml");
    let located = |error: ManifestError| match error {
        ManifestError::Parse { path, message, .. } => parse_error(&root.join(path), message),
        ManifestError::Read { path, message } => LocateError::ManifestReadError {
            path: root.join(path),
            message,
        },
        other => LocateError::ManifestReadError {
            path: root.join(&manifest),
            message: other.to_string(),
        },
    };
    let document = callisto_manifests::parse_manifest(&manifest, manifest_text).map_err(located)?;
    let Some(governing) = nested
        .reads
        .enclosing(&manifest, &document, callisto_manifests::read_manifest_text(root))
        .map_err(located)?
    else {
        return Ok(true);
    };
    let governing_dir = governing.parent().unwrap_or(Path::new(""));
    // A workspace named by `package.workspace` from outside the package's own ancestry has no path to judge by.
    let Ok(within) = rel.strip_prefix(governing_dir) else {
        return Ok(true);
    };
    if governing_dir.as_os_str().is_empty() || within.as_os_str().is_empty() {
        return Ok(true);
    }
    if !nested.cargo.contains_key(governing_dir) {
        let membership = read_cargo_membership(&root.join(governing_dir))?;
        nested.cargo.insert(governing_dir.to_path_buf(), membership);
    }
    Ok(nested.cargo[governing_dir].admits(within, false))
}

